// Süre biçimi (dk:sn) — grup karelerinde her katılımcının konuşma süresi için (modül seviyesi).
function _sureBicim(sn) {
  sn = Math.max(0, Math.round(sn || 0));
  const sa = Math.floor(sn / 3600), dk = Math.floor((sn % 3600) / 60), s = sn % 60;
  const iki = (n) => (n < 10 ? "0" + n : "" + n);
  return sa > 0 ? (sa + ":" + iki(dk) + ":" + iki(s)) : (iki(dk) + ":" + iki(s));
}
// GRUP GÖRÜŞMESİ — her uzak katılımcının bir "karesi" (video+ses). LiveKit track'lerini kendi <video>/<audio>'suna bağlar.
function GrupKare({ p }) {
  const vRef = useRef(null); const aRef = useRef(null);
  const [ad, setAd] = useState((p && (p.name || p.identity)) || "");
  const [kameraVar, setKameraVar] = useState(false);
  const [sn, setSn] = useState(0);
  useEffect(() => { const bas = Date.now(); const iv = setInterval(() => setSn(Math.round((Date.now() - bas) / 1000)), 1000); return () => clearInterval(iv); }, []);
  useEffect(() => {
    if (!p) return;
    let iptal = false;
    const bagla = () => {
      if (iptal) return;
      try {
        const vp = p.getTrackPublication && p.getTrackPublication(Track.Source.Camera);
        if (vp && vp.videoTrack && vRef.current) { try { vp.videoTrack.attach(vRef.current); } catch (e) {} setKameraVar(!vp.isMuted); }
        else setKameraVar(false);
        const apb = p.getTrackPublication && p.getTrackPublication(Track.Source.Microphone);
        if (apb && apb.audioTrack && aRef.current) { try { apb.audioTrack.attach(aRef.current); } catch (e) {} }
      } catch (e) {}
    };
    bagla();
    const olay = () => bagla();
    try { p.on("trackSubscribed", olay); p.on("trackUnsubscribed", olay); p.on("trackMuted", olay); p.on("trackUnmuted", olay); } catch (e) {}
    try { const meta = p.metadata ? JSON.parse(p.metadata) : null; if (meta && meta.ad) setAd(meta.ad); else setAd(p.name || p.identity || ""); } catch (e) { setAd((p && (p.name || p.identity)) || ""); }
    return () => { iptal = true; try { p.off("trackSubscribed", olay); p.off("trackUnsubscribed", olay); p.off("trackMuted", olay); p.off("trackUnmuted", olay); } catch (e) {} };
  }, [p]);
  return (
    <div className="grup-kare">
      <video ref={vRef} autoPlay playsInline style={{ display: kameraVar ? "block" : "none" }} />
      {!kameraVar && <span className="grup-kare-harf">{(ad || "?").trim()[0] ? (ad || "?").trim()[0].toUpperCase() : "?"}</span>}
      <audio ref={aRef} autoPlay playsInline />
      <span className="grup-kare-ad notranslate" translate="no">{ad}</span>
      <span className="grup-kare-sure notranslate" translate="no">{_sureBicim(sn)}</span>
    </div>
  );
}
// TEBRİK POSTERİNE (Cuma/Bayram/Doğum günü/Geçmiş olsun/Yeni yıl) DOĞRU YAZIYI CANVAS İLE BAS. Resim üreticisi yazıyı
// (özellikle Türkçe'yi) bozuyor ("Cumalar"->"Cumular"). Bu yüzden arka planı YAZISIZ üretip BAŞLIK + (biraz uzun) DUA/dileği
// BURADA doğru harflerle, şık altın yazıyla üstüne basıyoruz. Alt yazı uzunsa SATIRLARA sarılır (kesilmez).
function _tebrikYaziBas(dataUrl, baslik, altYazi) {
  return new Promise((resolve) => {
    try {
      const img = new Image(); img.crossOrigin = "anonymous";
      img.onload = () => {
        try {
          const W = img.naturalWidth || 1024, H = img.naturalHeight || 1024;
          const c = document.createElement("canvas"); c.width = W; c.height = H;
          const x = c.getContext("2d");
          x.drawImage(img, 0, 0, W, H);
          x.textAlign = "center"; x.textBaseline = "middle";
          // ALT YAZIYI (dua/dilek) kelime kelime SATIRLARA sar
          const f2 = Math.max(16, Math.round(W * 0.044));
          x.font = "600 " + f2 + "px Georgia,serif";
          const satirlar = [];
          (altYazi ? altYazi.split(/\s+/).filter(Boolean) : []).forEach((w) => {
            const dene = satirlar.length ? satirlar[satirlar.length - 1] + " " + w : w;
            if (satirlar.length && x.measureText(dene).width > W * 0.86) satirlar.push(w);
            else if (satirlar.length) satirlar[satirlar.length - 1] = dene; else satirlar.push(w);
          });
          const altN = Math.min(satirlar.length, 4);
          // Okunurluk için alt bölgeye yumuşak KOYU KAHVE bant (siyah DEĞİL — anayasa); yazı yüksekliğine göre büyür
          const bandY = H * (altN >= 3 ? 0.48 : altN >= 1 ? 0.55 : 0.62);
          const g = x.createLinearGradient(0, bandY, 0, H);
          g.addColorStop(0, "rgba(24,14,0,0)"); g.addColorStop(1, "rgba(24,14,0,0.72)");
          x.fillStyle = g; x.fillRect(0, bandY, W, H - bandY);
          // BAŞLIK — büyük şık altın; sığmıyorsa font küçülür (KESİLMEZ)
          let f = Math.round(W * 0.086);
          x.font = "700 " + f + "px Georgia,'Times New Roman',serif";
          while (x.measureText(baslik).width > W * 0.9 && f > 20) { f -= 2; x.font = "700 " + f + "px Georgia,serif"; }
          const bY = H * (altN >= 2 ? 0.66 : altN === 1 ? 0.72 : 0.80);
          const yg = x.createLinearGradient(0, bY - f, 0, bY + f);
          yg.addColorStop(0, "#fff3c4"); yg.addColorStop(0.5, "#ffd700"); yg.addColorStop(1, "#e6b422");
          x.shadowColor = "rgba(0,0,0,0.6)"; x.shadowBlur = Math.round(W * 0.02); x.shadowOffsetY = 2;
          x.fillStyle = yg; x.fillText(baslik, W / 2, bY);
          // ALT SATIRLAR (biraz uzun dua/dilek)
          if (altN) {
            x.font = "600 " + f2 + "px Georgia,serif"; x.fillStyle = "#ffe9a8"; x.shadowBlur = Math.round(W * 0.012);
            let ay = bY + f * 0.78;
            for (let i = 0; i < altN; i++) { x.fillText(satirlar[i], W / 2, ay); ay += f2 * 1.38; }
          }
          resolve(c.toDataURL("image/jpeg", 0.92));
        } catch (e) { resolve(dataUrl); }
      };
      img.onerror = () => resolve(dataUrl);
      img.src = dataUrl;
    } catch (e) { resolve(dataUrl); }
  });
}
