    if (!key || !kaynakMetin) return;
    const mevcut = ceviri[key];
    if (mevcut && mevcut.metin) { setCeviri((s) => ({ ...s, [key]: { ...mevcut, acik: !mevcut.acik } })); return; }
    if (mevcut && mevcut.yuk) return;
